function matches(s,r={}){for(const[k,v]of Object.entries(r.flags||{}))if(s.flags[k]!==v)return false;if(r.minTrust&&s.player.trust<r.minTrust)return false;if(r.maxTrust!==undefined&&s.player.trust>r.maxTrust)return false;if(r.relationship){const rel=s.relationships[r.relationship.actorId];if(!rel||rel.trust<(r.relationship.minTrust??0))return false;}return true;}
