export function advanceWorld(s,dt){if(s.finished)return s;const total=(s.remainder||0)+(Number.isFinite(Number(dt))?Math.max(0,Number(dt)):0);const steps=Math.min(Math.floor(total),DAY_DURATION-s.time);s.remainder=total-Math.floor(total);for(let i=0;i<steps;i++)tick(s);return s;}
