export function validateWorld(s){const errors=[];if(!s||typeof s!=='object'||!s.actors||!s.districts||!Array.isArray(s.events)||!Array.isArray(s.promises))return ['Malformed world'];if(!Number.isFinite(s.time)||s.time<0||s.time>DAY_DURATION)errors.push('Invalid time');for(const a of Object.values(s.actors)){if(!a||!Array.isArray(a.beliefs)||!Array.isArray(a.commitments)||!a.social||!a.values||!a.needs||!a.resources||!a.economic){errors.push('Malformed actor');continue;}if(!s.districts[a.district])errors.push(`Unknown district: ${a.id}`);for(const b of a.beliefs){if(b.learnedAt>s.time)errors.push(`Future knowledge: ${a.id}`);if(b.source==='witness'){const e=s.events.find(e=>e.id===b.sourceId);if(!e)errors.push(`Missing witness source: ${a.id}`);else if(b.observedDistrict!==e.district)errors.push(`Impossible witness location: ${a.id}`);}}if(a.decision&&(!Array.isArray(a.decision.candidates)||!a.decision.candidates.some(c=>c.id===a.decision.selected&&c.allowed)))errors.push(`Invalid decision: ${a.id}`);}for(const d of Object.values(s.districts))for(const k of ['tension','density','supplies','access','solidarity'])if(!Number.isFinite(d[k])||d[k]<0||d[k]>100)errors.push(`Invalid district condition: ${k}`);for(const p of s.promises)if(!['open','kept','broken'].includes(p.status))errors.push('Invalid promise status');if(new Set(s.events.map(e=>e.id)).size!==s.events.length)errors.push('Duplicate events');if(s.finished&&!s.ending)errors.push('Missing ending');return errors;}
